COPY (SELECT oi.order_item_id AS item_id, o.order_id, o.customer_id, (o.order_ts AT TIME ZONE 'UTC')::date AS order_date, (oi.quantity * oi.unit_price)::numeric(12,2) AS line_revenue FROM eca_project2.orders o JOIN eca_project2.order_items oi ON oi.order_id=o.order_id WHERE o.status='paid' AND o.order_ts >= TIMESTAMPTZ '2025-01-01 00:00:00+00' AND o.order_ts < TIMESTAMPTZ '2025-04-01 00:00:00+00' ORDER BY oi.order_item_id) TO STDOUT WITH CSV HEADER;
